function renderReportsBio(){const total=(state.measurements||[]).filter(x=>x.source!=='demo').length;return renderReportsV3()+`<section class="card card-pad bio-report-addition">${header('Cobertura de biomarcadores','Inventario de los 39 parámetros planteados')}<div class="bio-report-stats"><div><strong>${bioObservedCount()} / ${BIO_METRICS.length}</strong><span>Parámetros con datos, incluyendo ejemplos</span></div><div><strong>${total}</strong><span>Registros adicionales no demostrativos</span></div><div><strong>${BIO_METRICS.filter(m=>m.kind==='experimental').length}</strong><span>Variables de investigación</span></div></div><p class="form-help">El CSV incluye ahora todas las observaciones de biomarcadores con fecha, unidad y origen; los indicadores por IA sin modelo permanecen vacíos.</p></section>`}

function seed(){
 const readings=[];
 for(let i=34;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);d.setHours(8,35,0,0);readings.push({id:`seed_r_${i}`,at:d.toISOString(),hrv:Math.round(48+Math.sin(i*.72)*10+Math.cos(i*.31)*6-(i===0?10:0)),bpm:Math.round(70+Math.sin(i*.49)*5+Math.cos(i*.22)*3),temp:Math.round((33.2+Math.sin(i*.35)*.5+Math.cos(i*.73)*.24)*10)/10,sleep:Math.round((6.7+Math.sin(i*.75)*1.15+Math.cos(i*.29)*.45)*10)/10,activity:Math.max(800,Math.round(4500+Math.cos(i*.5)*1400+Math.sin(i*.26)*1000)),risk:Math.max(12,Math.min(89,Math.round(42+Math.sin(i*.57)*19+Math.cos(i*.2)*13)) ),source:'demo'});}
 readings[readings.length-1]={...readings[readings.length-1],hrv:42,bpm:76,temp:33.7,sleep:5.9,activity:3900,risk:78};
 const alertAt=new Date(Date.now()-5*3600000).toISOString();
 return {readings,plans:[],measurements:demoMeasurementSamples(),episodes:[{id:'seed_ep_1',at:daysBack(2,16),intensity:7,duration:3.5,symptoms:['Fotofobia','Náuseas'],triggers:'Poco descanso',medication:'Tratamiento de ejemplo',notes:'Episodio de muestra',source:'manual',followed:null},{id:'seed_ep_2',at:daysBack(6,9),intensity:5,duration:2,symptoms:['Sensibilidad al sonido'],triggers:'Estrés',medication:'No registrado',notes:'',source:'manual',followed:null},{id:'seed_ep_3',at:daysBack(11,13),intensity:8,duration:5,symptoms:['Fotofobia','Aura'],triggers:'Luz intensa',medication:'Tratamiento de ejemplo',notes:'',source:'manual',followed:null},{id:'seed_ep_4',at:daysBack(21,12),intensity:6,duration:4,symptoms:['Náuseas'],triggers:'Sin identificar',medication:'No registrado',notes:'',source:'manual',followed:null}],medications:[{id:'seed_med_1',name:'Tratamiento de ejemplo',dose:'Según prescripción',purpose:'Para episodios',start:dayKey(daysBack(24)),notes:'Medicamento ficticio para ilustrar la interfaz',logs:[{id:'seed_log_1',at:daysBack(2,16),amount:'Según pauta',note:'Registro de prueba'}]}],alerts:[{id:'seed_alert_1',at:alertAt,horizon:1,risk:78,status:'pending',ready:true,feedback:null}],settings:{notifications:true,reminder:true,threshold:70,prodrome:false,alertVibration:false,alertTone:false},activity:[]};
}
function load(){try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(data&&Array.isArray(data.readings)&&Array.isArray(data.episodes)&&Array.isArray(data.medications)&&Array.isArray(data.alerts)&&data.settings){if(!Array.isArray(data.measurements))data.measurements=demoMeasurementSamples();if(!Array.isArray(data.plans))data.plans=[];data.settings.prodrome=Boolean(data.settings.prodrome);data.settings.alertVibration=Boolean(data.settings.alertVibration);data.settings.alertTone=Boolean(data.settings.alertTone);return data}}}catch(e){console.warn('No se pudo leer la información local',e)}return seed()}
let state=load();
const ui={section:'overview',period:7,reportRange:30,episodeFilter:'all',modal:null,notifications:false,mobileMenu:false,monitorMode:'overview',metricCategory:'all',metricSearch:'',metricSelected:'bpm',reportSymptom:'all',reportMetric:'hrv',reportFrom:'',reportTo:''};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('No se pudo guardar: el navegador bloquea el almacenamiento local.','error')}}
function sortByDate(items){return [...items].sort((a,b)=>new Date(b.at)-new Date(a.at))}
function withinDays(items,days){const cutoff=Date.now()-days*86400000;return items.filter(r=>new Date(r.at).getTime()>=cutoff)}
function lastReading(){return sortByDate(state.readings)[0]}
function demoRisk(){return sortByDate(state.readings.filter(r=>Number.isFinite(r.risk)))[0]?.risk??78}
function activeAlerts(){return sortByDate(state.alerts.filter(a=>a.status==='pending'))}
function latestAlert(){return activeAlerts()[0]}
function dataCount(days){return withinDays(state.episodes,days).length}
function avg(items,key){const ar=items.map(i=>Number(i[key])).filter(Number.isFinite);return ar.length?ar.reduce((a,b)=>a+b,0)/ar.length:0}
function pageIntro(kicker,title,subtitle,buttons=''){return `<div class="page-intro"><div><span class="eyebrow">${kicker}</span><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div>${buttons?`<div class="page-actions">${buttons}</div>`:''}</div>`}
function btn(text,action,style='primary',extra=''){return `<button type="button" class="btn btn-${style}" data-action="${action}" ${extra}>${text}</button>`}
function header(title,sub='',action=''){return `<div class="card-heading"><div><h2>${title}</h2>${sub?`<div class="subline">${sub}</div>`:''}</div>${action}</div>`}
function pill(text,tone){return `<span class="pill ${tone}">${esc(text)}</span>`}
function empty(iconName,title,text,button=''){return `<div class="empty-state"><span class="empty-icon">${icon(iconName,23)}</span><strong>${title}</strong><p>${text}</p>${button}</div>`}
const NAV=[['overview','grid','Resumen'],['monitoring','activity','Monitoreo'],['episodes','brain','Mis episodios'],['meds','pill','Medicamentos'],['reports','report','Informes'],['learn','info','Aprender'],['settings','settings','Configuración']];
function renderNavigation(){
 const item=([id,ic,label])=>`<button type="button" class="nav-link ${ui.section===id?'active':''}" data-action="nav" data-section="${id}" ${ui.section===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='episodes'&&dataCount(30)?`<span class="nav-counter">${dataCount(30)}</span>`:''}</button>`;
 document.querySelector('#desktop-nav').innerHTML=NAV.slice(0,5).map(item).join('');document.querySelector('#secondary-nav').innerHTML=NAV.slice(5).map(item).join('');
 document.querySelector('#mobile-nav').innerHTML=[NAV[0],NAV[1],NAV[2],NAV[3],NAV[4]].map(([id,ic,label])=>`<button class="mobile-tab ${ui.section===id?'active':''}" data-action="nav" data-section="${id}">${icon(ic)}<span>${id==='episodes'?'Episodios':label}</span></button>`).join('');
 document.querySelector('#section-breadcrumb').textContent=NAV.find(n=>n[0]===ui.section)?.[2]||'Resumen';
 document.querySelector('.sidebar').classList.toggle('open',ui.mobileMenu);document.querySelector('#mobile-overlay').classList.toggle('hidden',!ui.mobileMenu);
 document.querySelector('.mobile-menu').innerHTML=icon('menu');document.body.classList.toggle('prodrome-mode',Boolean(state.settings.prodrome));document.querySelector('#calm-toggle')?.setAttribute('aria-pressed',String(Boolean(state.settings.prodrome)));document.querySelector('#calm-toggle-label').textContent=state.settings.prodrome?'Modo calma activo':'Modo calma';document.querySelector('#notification-icon').innerHTML=icon('bell');
 document.querySelector('#notification-indicator').classList.toggle('hidden',!activeAlerts().length);
 document.querySelector('#sidebar-device').innerHTML=`<div class="device-widget-head">${icon('bluetooth',17)} Dispositivo de prueba</div><p>El anillo real no está conectado. Los valores iniciales son simulados.</p><button type="button" data-action="nav" data-section="settings" class="small-link">Ver integración ${icon('arrow',12)}</button>`;
}
function graphSVG(items,field,minValue,maxValue,color='#143cef',id='main'){
 const W=680,H=230,P={l:43,r:14,t:15,b:31};const vals=items.map(d=>Number(d[field])).filter(Number.isFinite);
 if(!vals.length)return `<div class="empty-state">No hay valores para representar.</div>`;
 let low=minValue??Math.floor(Math.min(...vals)*.85),high=maxValue??Math.ceil(Math.max(...vals)*1.12);
 if(high-low<2)high=low+2;
 const X=i=>P.l+(items.length===1?.5:i/(items.length-1))*(W-P.l-P.r);
 const Y=v=>P.t+(high-v)/(high-low)*(H-P.t-P.b);
 const valid=items.map((d,i)=>({x:X(i),y:Y(Number(d[field])),good:Number.isFinite(Number(d[field]))})).filter(p=>p.good);
 if(!valid.length)return '<div class="empty-state">Sin valores</div>';
 const points=valid.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
 const area=`${valid[0].x},${H-P.b} ${points} ${valid[valid.length-1].x},${H-P.b}`;
 const lines=[0,1,2,3,4].map(i=>{const y=P.t+(H-P.t-P.b)*i/4;return `<line x1="${P.l}" y1="${y}" x2="${W-P.r}" y2="${y}" class="chart-gridline"/><text class="chart-axis-label" x="${P.l-9}" y="${y+3.5}" text-anchor="end">${Math.round(high-(high-low)*i/4)}</text>`}).join('');
 const idx=[0,Math.floor((items.length-1)/3),Math.round((items.length-1)*2/3),items.length-1];const labels=[...new Set(idx)].map(i=>`<text class="chart-axis-label" x="${X(i)}" y="${H-6}" text-anchor="middle">${formatDate(items[i].at,{day:'numeric',month:'short'})}</text>`).join('');
 return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Gráfico de ${esc(field)} con ${items.length} datos"><defs><linearGradient id="${id}Gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".17"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${lines}<polygon points="${area}" fill="url(#${id}Gradient)"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/><circle cx="${valid[valid.length-1].x}" cy="${valid[valid.length-1].y}" r="5" stroke="${color}" stroke-width="3" fill="white" vector-effect="non-scaling-stroke"/>${labels}</svg>`;
}
function riskChart(days,id='risk'){
 const readings=sortByDate(withinDays(state.readings.filter(r=>Number.isFinite(r.risk)),days)).reverse();
 return `<div class="graph-wrap">${graphSVG(readings,'risk',0,100,'#143cef',id)}</div>`;
}
function periodSelector(){return `<div class="segmented" aria-label="Período de análisis">${[7,14,30].map(n=>`<button class="segment ${ui.period===n?'active':''}" data-action="period" data-period="${n}">${n} días</button>`).join('')}</div>`}
function activityFeed(limit=5){
 const events=[...state.episodes.map(e=>({at:e.at,type:'episode',title:'Episodio de migraña registrado',detail:`Intensidad ${e.intensity}/10 · ${formatNumber(e.duration,1)} h`,icon:'brain'})),...state.readings.filter(r=>r.source==='manual').map(r=>({at:r.at,type:'reading',title:'Lectura manual registrada',detail:`Pulso ${r.bpm} lpm · VFC ${r.hrv} ms`,icon:'activity'})),...state.alerts.map(a=>({at:a.at,type:a.status==='pending'?'alert':'result',title:a.status==='pending'?'Alerta simulada generada':'Resultado de alerta registrado',detail:a.status==='pending'?`Riesgo simulado ${a.risk}%`:`Resultado: ${a.feedback?.migraine==='yes'?'migraña':'sin migraña'}`,icon:a.status==='pending'?'bell':'check'})),...state.medications.flatMap(m=>m.logs.map(l=>({at:l.at,type:'medicine',title:'Toma registrada',detail:`${m.name} · ${l.amount}`,icon:'pill'})))].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,limit);
 if(!events.length)return empty('activity','Sin movimientos','Tu actividad se mostrará aquí cuando registres información.');
 return events.map(e=>`<div class="activity-item"><div class="activity-marker ${e.type==='episode'||e.type==='alert'?'pink':e.type==='result'?'green':''}">${icon(e.icon)}</div><div class="activity-main"><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p></div><span class="activity-time">${ago(e.at)}</span></div>`).join('');
}
function metricCard(label,value,unit,kind,note,trend=''){return `<div class="card metric-card"><div class="metric-top"><span class="metric-icon ${kind==='heart'?'pink':kind==='temperature'?'purple':kind==='moon'?'green':'blue'}">${icon(kind)}</span><span class="metric-trend neutral">Última lectura</span></div><span class="metric-label">${label}</span><div class="metric-value">${value} <span>${unit}</span></div><div class="metric-foot">${note}</div></div>`}
function sleepCard(){const vals=sortByDate(withinDays(state.readings,7)).reverse().slice(-7);return `<div class="card card-pad">${header('Descanso de los últimos días','Horas de sueño registradas')}${vals.length?`<div class="sleep-summary"><div><span class="section-kicker">Promedio</span><strong>${formatNumber(avg(vals,'sleep'),1)} <small>horas / noche</small></strong></div>${pill('Seguimiento de sueño','blue')}</div><div class="sleep-bars">${vals.map(r=>`<div class="sleep-day"><div class="sleep-bar-track"><div class="sleep-bar" style="height:${Math.max(8,Math.min(100,(r.sleep/10)*100))}%"></div></div><span>${formatDate(r.at,{weekday:'short'})}</span></div>`).join('')}</div>`:empty('moon','Sin datos','Agregá lecturas para ver el descanso.') }<div class="little-note">${icon('info',13)} El descanso es una variable observada, no confirma ni descarta una migraña.</div></div>`}
function renderOverview(){
 const latest=lastReading(),risk=demoRisk(),alert=latestAlert();
 return `${pageIntro('TU BIENESTAR, EN PRIMER LUGAR','Buen día, paciente 👋','Este es tu espacio para comprender tus datos y registrar cómo te sentís.',btn(`${icon('plus')} Registrar episodio`,'new-episode','primary')+btn(`${icon('plus')} Cargar valores`,'new-reading','outline'))}
 <section class="hero-card"><div class="hero-copy"><div class="hero-status"><i></i> ${alert?'ALERTA DE DEMOSTRACIÓN':'MONITOREO DE DEMOSTRACIÓN'}</div><h2>${alert?'Hay una alerta para revisar':'Tu bienestar, en perspectiva'}</h2><p>${alert?`Se simuló una probabilidad de migraña para una ventana de ${horizonText(alert.horizon)}. Registrá si ocurrió y qué medidas tomaste.`:'Este panel reúne tus registros de salud. La predicción mostrada es una simulación, no una evaluación clínica.'}</p><div class="hero-actions">${btn(`${icon('bell')} ${alert?'Revisar y responder alerta':'Simular una alerta'}`,alert?'view-alert':'simulate-alert','white')}${btn(`${icon('trend')} Explorar métricas`,'nav','outline','data-section="monitoring" style="background:rgba(255,255,255,.1);color:white;border-color:rgba(255,255,255,.3)"')}</div></div><div class="hero-visual"><span class="floating-ring"></span><span class="floating-ring r2"></span><span class="floating-star">✦</span><div class="risk-disc" style="--value:${risk*3.6}deg"><div class="risk-disc-inner"><div class="value">${risk}<small>%</small></div><span class="risk-label">riesgo simulado</span></div></div></div></section>
 <div class="metrics-grid">${metricCard('Frecuencia cardíaca',bioLastValue('bpm',0),'lpm','heartbeat','Último dato registrado')}${metricCard('Variabilidad cardíaca',bioLastValue('hrv',0),'ms','activity','VFC · indicador de seguimiento')}${metricCard('Temperatura cutánea',bioLastValue('temp',1),'°C','temperature','Medición superficial')}${metricCard('Sueño',bioLastValue('sleep',1),'horas','moon','Última noche registrada')}</div>
 <div class="dashboard-grid"><section class="card card-pad chart-card">${header('Evolución del riesgo simulado','Solo datos ficticios del prototipo',periodSelector())}${riskChart(ui.period,'overviewRisk')}<div class="chart-caption"><span class="legend"><i class="line"></i> Puntaje ilustrativo · no validado</span><span>${ui.period} días</span></div></section><section class="card card-pad">${header('Recomendaciones generales','Medidas de autocuidado, no sustituyen atención médica')}<div class="guidance-item"><span class="guidance-symbol">${icon('water')}</span><div><strong>Mantené tu hidratación</strong><p>Registrá cómo te sentís y mantené tus hábitos habituales de cuidado.</p></div></div><div class="guidance-item"><span class="guidance-symbol pink">${icon('moon')}</span><div><strong>Priorizá el descanso</strong><p>Podés anotar sueño, estrés y posibles desencadenantes.</p></div></div><div class="guidance-item"><span class="guidance-symbol green">${icon('clipboard')}</span><div><strong>Seguimiento de tus indicaciones</strong><p>Usá medicación únicamente de acuerdo con el plan de tu profesional.</p></div></div></section></div>
 <div class="lower-grid"><section class="card card-pad">${header('Actividad reciente','Eventos y registros de tu historial',`<button class="muted-action" data-action="nav" data-section="episodes">Ver episodios ${icon('arrow',13)}</button>`)}${activityFeed(4)}</section>${sleepCard()}</div>`;
}
function renderMonitoring(){
 if(ui.monitorMode==='catalog')return renderBiomarkerExplorer();
 const latest=lastReading();const subset=sortByDate(withinDays(state.readings,ui.period)).reverse();
 return `${pageIntro('MIS BIOMARCADORES','Monitoreo de salud','Revisá la evolución de tus valores y registrá mediciones manuales.',btn(`${icon('plus')} Agregar medición`,'new-reading')+btn(`${icon('activity')} Ver 39 biomarcadores`,'open-catalog','outline'))}<div class="inline-alert info" style="margin-bottom:20px">${icon('info')} Las mediciones precargadas son ejemplos. No hay conexión Bluetooth ni análisis médico real en este prototipo.</div>
 <div class="two-column"><div class="stack"><section class="card card-pad">${header('Variabilidad de la frecuencia cardíaca','VFC · milisegundos',periodSelector())}<div class="graph-wrap">${graphSVG(subset,'hrv',20,80,'#865dec','hrv')}</div><div class="chart-caption"><span class="legend"><i class="line" style="background:#865dec"></i> Valor registrado</span><strong>Último: ${bioLastValue('hrv')} ms</strong></div></section><section class="card card-pad">${header('Frecuencia cardíaca','Latidos por minuto')}<div class="graph-wrap">${graphSVG(subset,'bpm',45,100,'#f43182','bpm')}</div><div class="chart-caption"><span class="legend"><i class="line" style="background:#f43182"></i> Frecuencia cardíaca</span><strong>Último: ${bioLastValue('bpm')} lpm</strong></div></section><section class="card card-pad">${header('Temperatura cutánea','Temperatura superficial expresada en °C')}<div class="graph-wrap">${graphSVG(subset,'temp',31,36,'#10a99b','temp')}</div><div class="chart-caption"><span class="legend"><i class="line" style="background:#10a99b"></i> Temperatura</span><strong>Última: ${bioLastValue('temp',1)} °C</strong></div></section></div>
 <div class="stack"><section class="card card-pad">${header('Última medición','Valores registrados en el historial')}${latest?`<div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon pink">${icon('heartbeat')}</span><div><strong>Frecuencia cardíaca</strong><small>Pulso</small></div></div><span class="reading-value">${bioLastValue('bpm')} <small>lpm</small></span></div><div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon blue">${icon('activity')}</span><div><strong>Variabilidad cardíaca</strong><small>VFC</small></div></div><span class="reading-value">${bioLastValue('hrv')} <small>ms</small></span></div><div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon purple">${icon('temperature')}</span><div><strong>Temperatura cutánea</strong><small>Superficie de piel</small></div></div><span class="reading-value">${bioLastValue('temp',1)} <small>°C</small></span></div><div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon green">${icon('moon')}</span><div><strong>Sueño</strong><small>Horas de descanso</small></div></div><span class="reading-value">${bioLastValue('sleep',1)} <small>h</small></span></div><div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon blue">${icon('trend')}</span><div><strong>Actividad</strong><small>Pasos aproximados</small></div></div><span class="reading-value">${bioLastValue('activity')} <small>pasos</small></span></div><p class="form-help">Último registro: ${formatDate(latest.at)} · ${formatHour(latest.at)} · ${latest.source==='demo'?'dato ficticio':'carga manual'}</p>`:empty('activity','Sin lecturas','Agregá tu primera medición.')}</section><section class="card card-pad">${header('Mi anillo','Estado de integración')}<div class="device-illustration"><div class="ring-model" aria-label="Ilustración esquemática del anillo"></div></div><div class="device-state"><h3>Sin conexión real</h3><p>En esta versión, los datos se pueden cargar manualmente. La sincronización BLE se integrará más adelante.</p>${btn('Ver detalles de integración','device-info','outline')}</div></section><section class="card card-pad">${header('Datos y contexto')}<div class="guidance-item"><span class="guidance-symbol">${icon('shield')}</span><div><strong>Información personal</strong><p>Los datos se almacenan en este navegador, sin conexión al servidor.</p></div></div><div class="guidance-item"><span class="guidance-symbol pink">${icon('info')}</span><div><strong>Interpretación clínica</strong><p>Los valores aislados no permiten diagnosticar o predecir migrañas.</p></div></div></section></div></div>`;
}
function episodesPeriod(){return ui.episodeFilter==='all'?sortByDate(state.episodes):sortByDate(withinDays(state.episodes,Number(ui.episodeFilter)))}
function renderEpisodes(){
 const ep=episodesPeriod();const last30=withinDays(state.episodes,30);const intensity=last30.length?formatNumber(avg(last30,'intensity'),1):'—';const hours=last30.length?formatNumber(avg(last30,'duration'),1):'—';
 return `${pageIntro('DIARIO PERSONAL','Mis episodios','Registrá los síntomas, duración y posibles desencadenantes para identificar patrones.',btn(`${icon('plus')} Registrar migraña`,'new-episode'))}
 <div class="stat-grid" style="margin-bottom:20px"><div class="stat-tile"><div class="k">Episodios · últimos 30 días</div><div class="v">${last30.length}</div><div class="s">Registros en el diario</div></div><div class="stat-tile"><div class="k">Intensidad promedio</div><div class="v">${intensity}${last30.length?'<span style="font-size:12px;color:#9eabc0"> / 10</span>':''}</div><div class="s">Según los valores ingresados</div></div><div class="stat-tile"><div class="k">Duración promedio</div><div class="v">${hours}${last30.length?'<span style="font-size:12px;color:#9eabc0"> h</span>':''}</div><div class="s">Horas por episodio</div></div></div>
 <section class="card card-pad"><div class="filter-line"><div><h2 class="section-heading" style="margin:0 0 5px">Historial de episodios</h2><span class="page-subtitle">${ep.length} registros encontrados</span></div><div class="segmented">${[['all','Todos'],['7','7 días'],['30','30 días']].map(([v,l])=>`<button class="segment ${ui.episodeFilter===v?'active':''}" data-action="episode-filter" data-value="${v}">${l}</button>`).join('')}</div></div>${ep.length?ep.map(e=>`<div class="episode-card"><div><div class="episode-topline"><h3>${formatDate(e.at,{weekday:'long',day:'numeric',month:'long'})}</h3>${pill(e.source==='alert'?'Tras alerta':'Registro manual',e.source==='alert'?'pink':'blue')}</div><p>${icon('clock',13)} ${formatHour(e.at)} · Duración: ${formatNumber(e.duration,1)} horas</p><p><strong>Síntomas:</strong> ${e.symptoms?.length?esc(e.symptoms.join(', ')):'No indicados'}</p><p><strong>Posibles desencadenantes:</strong> ${esc(e.triggers||'No identificados')}</p><p><strong>Medicación utilizada:</strong> ${esc(e.medication||'No registrada')}</p>${e.notes?`<p><strong>Notas:</strong> ${esc(e.notes)}</p>`:''}</div><div class="intensity">${e.intensity}<small>intensidad / 10</small></div></div>`).join(''):empty('brain','No hay episodios registrados','Cada episodio que anotes aparecerá acá.',btn(`${icon('plus')} Agregar episodio`,'new-episode'))}</section>`;
}
function renderMeds(){
 const meds=state.medications;const logs=meds.flatMap(m=>m.logs.map(l=>({...l,medName:m.name}))).sort((a,b)=>new Date(b.at)-new Date(a.at));
 return `${pageIntro('TRATAMIENTOS','Mis medicamentos','Llevá un registro de tu medicación y de las tomas realizadas.',btn(`${icon('plus')} Agregar medicamento`,'new-med'))}<div class="inline-alert info" style="margin-bottom:20px">${icon('shield')} Esta sección es solo un registro personal; no prescribe medicamentos ni sugiere dosis. Seguí siempre las indicaciones de tu profesional de salud.</div><div class="two-column"><section class="card card-pad">${header('Tratamientos registrados',`${meds.length} en tu listado`)}${meds.length?meds.map(m=>`<div class="med-card"><div class="med-icon">${icon('pill')}</div><div class="med-body"><h3>${esc(m.name)}</h3><p><strong>Dosis registrada:</strong> ${esc(m.dose)}</p><p><strong>Uso:</strong> ${esc(m.purpose)} · Desde ${formatDate(m.start)}</p>${m.notes?`<p>${esc(m.notes)}</p>`:''}<div class="med-actions">${btn(`${icon('plus')} Registrar toma`,'dose','ghost',`data-id="${esc(m.id)}"`)}${btn(`${icon('trash')} Eliminar`,'delete-med','outline',`data-id="${esc(m.id)}"`)}</div></div></div>`).join(''):empty('pill','Aún no hay medicamentos','Añadí tu medicación para llevar un registro personal.',btn(`${icon('plus')} Agregar medicamento`,'new-med'))}</section><section class="card card-pad">${header('Historial de tomas','Información registrada por vos')}${logs.length?logs.slice(0,12).map(l=>`<div class="med-history"><span class="metric-icon purple" style="width:32px;height:32px">${icon('check',17)}</span><div><strong>${esc(l.medName)}</strong><div style="margin-top:4px">${esc(l.amount)}${l.note?' · '+esc(l.note):''}</div></div><span>${formatDate(l.at,{day:'numeric',month:'short'})}</span></div>`).join(''):empty('clock','No hay tomas','Cuando cargues una toma la vas a ver en este historial.')}</section></div>`;
}
function triggersFromEpisodes(ep){const counts={};ep.forEach(e=>{const t=String(e.triggers||'').trim();if(t&&t.toLowerCase()!=='sin identificar')t.split(/[,;]/).map(t=>t.trim()).filter(Boolean).forEach(t=>{counts[t]=(counts[t]||0)+1})});return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5)}
function reportWindow(){
 if(ui.reportRange==='custom' && ui.reportFrom && ui.reportTo){
  const start=new Date(ui.reportFrom+'T00:00:00'),end=new Date(ui.reportTo+'T00:00:00');end.setDate(end.getDate()+1);
  if(Number.isFinite(start.getTime())&&Number.isFinite(end.getTime())&&start<end)return {start:start.getTime(),end:end.getTime(),label:`Del ${formatDate(start)} al ${formatDate(new Date(end.getTime()-1))}`};
 }
 const days=typeof ui.reportRange==='number'?ui.reportRange:30;
 return {start:Date.now()-days*86400000,end:Date.now()+86400000,label:`Últimos ${days} días`};
}
function inReportWindow(obj){const at=new Date(obj.at).getTime(),range=reportWindow();return at>=range.start&&at<range.end;}
function reportSummary(){
 const ep=state.episodes.filter(e=>inReportWindow(e)&&(ui.reportSymptom==='all'||(e.symptoms||[]).some(s=>s===ui.reportSymptom)));
 const r=state.readings.filter(inReportWindow);
 const reviewed=state.alerts.filter(a=>a.status==='resolved'&&inReportWindow(a));
 return {ep,r,reviewed};
}
function reportMetricData(){const metric=BIO_BY_ID[ui.reportMetric]||BIO_BY_ID.hrv;return {metric,samples:metricSamples(metric.id).filter(inReportWindow).sort((a,b)=>new Date(a.at)-new Date(b.at))};}
function episodeDensity(ep){
 const range=reportWindow();const span=Math.max(1,(range.end-range.start)/86400000);const weeks=Math.max(1,Math.min(14,Math.ceil(span/7)));let bins=Array.from({length:weeks},(_,i)=>({count:0,start:new Date(range.start+i*7*86400000)}));
 ep.forEach(e=>{const i=Math.min(weeks-1,Math.max(0,Math.floor((new Date(e.at).getTime()-range.start)/(7*86400000))));bins[i].count++});
 const max=Math.max(1,...bins.map(b=>b.count));
 return `<div class="density-chart" role="img" aria-label="Densidad de episodios por semana: ${bins.map(b=>`semana ${formatDate(b.start,{day:'numeric',month:'short'})}, ${b.count}`).join('; ')}">${bins.map(b=>`<div class="density-bin"><span class="density-number">${b.count||'·'}</span><div class="density-track"><div class="density-fill" style="height:${b.count?Math.max(10,b.count/max*100):4}%"></div></div><span>${formatDate(b.start,{day:'numeric',month:'short'})}</span></div>`).join('')}</div><p class="form-help">Conteo semanal según los episodios registrados. No mide eficacia del algoritmo.</p>`;
}
function renderReportsV3(){
 const {ep,r,reviewed}=reportSummary(),range=reportWindow(),triggers=triggersFromEpisodes(ep),{metric,samples}=reportMetricData();
 const symptomOptions=['all',...new Set(state.episodes.flatMap(e=>e.symptoms||[]).filter(Boolean))].sort((a,b)=>a==='all'?-1:b==='all'?1:a.localeCompare(b,'es'));
 const originDemo=r.some(x=>x.source==='demo')||ep.some(x=>String(x.id).startsWith('seed'))||samples.some(x=>x.source==='demo');
 return `${pageIntro('INFORMES PERSONALIZADOS','Informes de salud','Seleccioná fechas, síntomas y biomarcadores para generar un resumen comprensible para el neurólogo.',btn(`${icon('download')} Exportar CSV`,'export-csv','outline')+btn(`${icon('print')} Guardar PDF`,'print-report'))}
 <section class="report-hero"><div><span class="eyebrow" style="color:#b5c7ff">MIGRARING BIO · INFORME PERSONAL</span><h2>Tu historia, organizada para la consulta</h2><p>Registro personal con mediciones y episodios. Todos los datos de demostración deben identificarse antes de compartir el documento.</p></div>${icon('report',70)}</section>
 <section class="card card-pad report-controls no-print">${header('Personalizar informe','Filtros aplicados a estadísticas, gráficos y exportación CSV')}
 <div class="report-control-grid"><div class="field"><label for="report-period">Período</label><select id="report-period" data-report-filter="period">${[[7,'Últimos 7 días'],[30,'Últimos 30 días'],[90,'Últimos 90 días'],['custom','Fechas personalizadas']].map(([v,l])=>`<option value="${v}" ${ui.reportRange===v?'selected':''}>${l}</option>`).join('')}</select></div>
 <div class="field"><label for="report-symptom">Síntoma</label><select id="report-symptom" data-report-filter="symptom">${symptomOptions.map(v=>`<option value="${esc(v)}" ${ui.reportSymptom===v?'selected':''}>${v==='all'?'Todos los síntomas':esc(v)}</option>`).join('')}</select></div>
 <div class="field"><label for="report-metric">Biomarcador</label><select id="report-metric" data-report-filter="metric">${BIO_METRICS.filter(m=>m.kind!=='ai').map(m=>`<option value="${esc(m.id)}" ${ui.reportMetric===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div></div>
 ${ui.reportRange==='custom'?`<div class="report-date-row"><div class="field"><label for="report-from">Desde</label><input type="date" id="report-from" data-report-date="from" value="${esc(ui.reportFrom)}" required></div><div class="field"><label for="report-to">Hasta</label><input type="date" id="report-to" data-report-date="to" value="${esc(ui.reportTo)}" required></div><span class="form-help">Si faltan fechas se muestran los últimos 30 días.</span></div>`:''}
 </section>
 <div class="report-period-description"><span>${icon('calendar',17)} ${esc(range.label)}</span><span>${ui.reportSymptom==='all'?'Todos los episodios':`Síntoma: ${esc(ui.reportSymptom)}`}</span></div>
 <div class="stat-grid" style="margin-bottom:20px"><div class="stat-tile"><div class="k">Episodios del filtro</div><div class="v">${ep.length}</div><div class="s">Registrados en el diario</div></div><div class="stat-tile"><div class="k">Intensidad promedio</div><div class="v">${ep.length?formatNumber(avg(ep,'intensity'),1):'—'}</div><div class="s">Escala 1–10</div></div><div class="stat-tile"><div class="k">Alertas respondidas</div><div class="v">${reviewed.length}</div><div class="s">Resultados de prueba</div></div></div>
 <div class="two-column"><div class="stack"><section class="card card-pad">${header('Densidad de episodios','Frecuencia semanal de episodios registrados')}${episodeDensity(ep)}</section>
 <section class="card card-pad">${header(`Evolución de ${esc(metric.name)}`,`Valores en ${esc(metric.unit)} y según procedencia`)}${samples.length?`<div class="graph-wrap report-chart">${graphSVG(samples,'value',null,null,'#655ce4','reportVariable')}</div><p class="form-help">${samples.length} lecturas · ${samples.some(x=>x.source==='demo')?'Contiene datos simulados.':'Registros manuales o de fuente externa.'} La relación temporal no implica causalidad.</p>`:empty('activity','No hay valores en estas fechas','Probá otro biomarcador o ampliá el período.')}</section>
 <section class="card card-pad">${header('Episodios y síntomas',range.label)}${ep.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Fecha</th><th>Intensidad</th><th>Síntomas</th><th>Duración</th></tr></thead><tbody>${sortByDate(ep).map(e=>`<tr><td>${formatDate(e.at,{day:'numeric',month:'short'})}</td><td>${e.intensity}/10</td><td>${esc((e.symptoms||[]).join(', ')||'—')}</td><td>${formatNumber(e.duration,1)} h</td></tr>`).join('')}</tbody></table></div>`:empty('brain','Sin episodios que coincidan','Quitá el filtro de síntoma o elegí otro período.')}</section></div>
 <div class="stack"><section class="card card-pad">${header('Desencadenantes anotados','Frecuencia descriptiva, no relación causal')}${triggers.length?triggers.map(([label,n])=>`<div class="trigger-row"><span>${esc(label)}</span><div class="progress-track"><div class="progress-fill" style="width:${n/triggers[0][1]*100}%"></div></div><strong>${n}</strong></div>`).join(''):empty('filter','Sin desencadenantes','Agregá información al diario para ver el resumen.')}</section>
 <section class="card card-pad">${header('Contexto del período','Valores independientes del filtro de síntomas')}<div class="reading-preview"><div class="reading-preview-left">${icon('moon')} <strong>Horas medias de sueño</strong></div><span class="reading-value">${r.length?formatNumber(avg(r,'sleep'),1):'—'} <small>h</small></span></div><div class="reading-preview"><div class="reading-preview-left">${icon('activity')} <strong>Lecturas fisiológicas</strong></div><span class="reading-value">${r.length}</span></div><div class="reading-preview"><div class="reading-preview-left">${icon('bell')} <strong>Alertas con seguimiento</strong></div><span class="reading-value">${reviewed.length}</span></div><p class="form-help">Los promedios de sueño incluyen lecturas disponibles, y no significan una correlación validada con migraña.</p></section>
 <section class="card card-pad report-disclosure">${header('Preparado para compartir','La descarga requiere tu autorización explícita')}<p class="settings-privacy">Podés descargar CSV o utilizar «Guardar PDF» en el navegador. La app <strong>no envía</strong> los datos al médico ni a un servidor. La exportación HL7 FHIR queda pendiente para una versión clínica.</p><div class="button-row" style="margin-top:14px">${btn('Exportar CSV','export-csv','outline')}${btn('Guardar PDF','print-report','ghost')}</div></section></div></div>
 <p class="report-note">${originDemo?'Atención: este informe contiene ejemplos ficticios. ':''}Herramienta para documentar información, no diagnóstico ni predicción validada. Cifrado, autenticación, HL7 FHIR y conformidad regulatoria son trabajos futuros.</p>`;
}
function renderReports(){const {ep,r,reviewed}=reportSummary();const triggers=triggersFromEpisodes(ep);const periodLabel=`Últimos ${ui.reportRange} días`;
 return `${pageIntro('MIS DATOS, MÁS CLAROS','Informes de salud','Visualizá tendencias y prepará un resumen para conversar con tu médico.',btn(`${icon('download')} Exportar CSV`,'export-csv','outline')+btn(`${icon('print')} Guardar como PDF`,'print-report'))}
 <div class="report-hero"><div><span class="eyebrow" style="color:#b5c7ff">REPORTE PERSONAL</span><h2>Resumen de seguimiento de migrañas</h2><p>Información autorregistrada y lecturas de demostración. Este documento no representa un diagnóstico ni una evaluación clínica.</p></div>${icon('report',76)}</div><div class="filter-line"><span class="page-subtitle">Período seleccionado: <strong>${periodLabel}</strong></span><div class="segmented">${[7,30,90].map(n=>`<button class="segment ${ui.reportRange===n?'active':''}" data-action="report-range" data-period="${n}">${n} días</button>`).join('')}</div>
 <div class="stat-grid" style="margin-bottom:20px"><div class="stat-tile"><div class="k">Episodios registrados</div><div class="v">${ep.length}</div><div class="s">En ${ui.reportRange} días</div></div><div class="stat-tile"><div class="k">Intensidad promedio</div><div class="v">${ep.length?formatNumber(avg(ep,'intensity'),1):'—'}</div><div class="s">Escala de 1 a 10</div></div><div class="stat-tile"><div class="k">Resultados de alertas</div><div class="v">${reviewed.length}</div><div class="s">Seguimientos completados</div></div></div>
 <div class="two-column"><div class="stack"><section class="card card-pad">${header('Evolución de VFC',periodLabel)}<div class="graph-wrap report-chart">${graphSVG(sortByDate(r).reverse(),'hrv',20,80,'#805bea','reportHRV')}</div><div class="chart-caption"><span class="legend"><i class="line" style="background:#805bea"></i> Variabilidad cardíaca</span><span>Promedio: ${r.length?formatNumber(avg(r,'hrv'),0)+' ms':'—'}</span></div></section><section class="card card-pad">${header('Episodios registrados',periodLabel)}${ep.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Fecha</th><th>Intensidad</th><th>Duración</th><th>Desencadenante</th></tr></thead><tbody>${sortByDate(ep).slice(0,12).map(e=>`<tr><td>${formatDate(e.at,{day:'numeric',month:'short'})}</td><td>${e.intensity}/10</td><td>${formatNumber(e.duration,1)} h</td><td>${esc(e.triggers||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('brain','Sin episodios en este período','Probá ampliar el período o registrar un episodio.')}</section></div><div class="stack"><section class="card card-pad">${header('Posibles desencadenantes','Frecuencia entre tus registros')}${triggers.length?triggers.map(([label,num])=>`<div class="trigger-row"><span title="${esc(label)}">${esc(label)}</span><div class="progress-track"><div class="progress-fill" style="width:${Math.round(100*num/triggers[0][1])}%"></div></div><strong>${num}</strong></div>`).join(''):empty('filter','Sin desencadenantes identificados','Los factores que registres aparecerán en este resumen.')}</section><section class="card card-pad">${header('Lecturas y seguimiento')}<div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon blue">${icon('activity')}</span><div><strong>Lecturas fisiológicas</strong><small>Registradas en el período</small></div></div><span class="reading-value">${r.length}</span></div><div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon green">${icon('moon')}</span><div><strong>Descanso promedio</strong><small>Por noche registrada</small></div></div><span class="reading-value">${r.length?formatNumber(avg(r,'sleep'),1):'—'} <small>h</small></span></div><div class="reading-preview"><div class="reading-preview-left"><span class="metric-icon pink">${icon('heart')}</span><div><strong>Pulso promedio</strong><small>Frecuencia cardíaca</small></div></div><span class="reading-value">${r.length?formatNumber(avg(r,'bpm'),0):'—'} <small>lpm</small></span></div></section><section class="card card-pad">${header('Compartir con mi médico')}<p class="settings-privacy">Descargá tus registros como CSV o imprimí esta vista como PDF para compartirla vos mismo. Este prototipo no envía datos a ninguna clínica ni a terceros.</p><div class="button-row" style="margin-top:15px">${btn(`${icon('download')} CSV`,'export-csv','outline')}${btn(`${icon('print')} PDF`,'print-report','ghost')}</div></section></div></div><p class="report-note" style="margin-top:20px">Datos de prueba: los registros precargados y las probabilidades son ficticios. Los datos que agregues manualmente pueden utilizarse únicamente como diario personal; no son una evaluación médica.</p>`;
}
function renderSettings(){const s=state.settings;return `${pageIntro('PREFERENCIAS','Configuración','Administrá las opciones del prototipo, la privacidad y la exportación de tus registros.')}
 <div class="two-column"><div class="stack"><section class="card card-pad">${header('Notificaciones y alertas','Preferencias visuales de la interfaz')}<div class="settings-row"><div><strong>Notificaciones dentro de la app</strong><p>Mostrar avisos cuando generás una alerta de prueba.</p></div><button aria-label="Activar o desactivar notificaciones" aria-pressed="${s.notifications}" class="switch ${s.notifications?'on':''}" data-action="toggle-setting" data-setting="notifications"></button></div><div class="settings-row"><div><strong>Recordatorio de seguimiento</strong><p>Mostrar la solicitud de respuesta luego de la ventana estimada.</p></div><button aria-label="Activar o desactivar seguimiento" aria-pressed="${s.reminder}" class="switch ${s.reminder?'on':''}" data-action="toggle-setting" data-setting="reminder"></button></div><div class="settings-row"><div><strong>Umbral ilustrativo para simulaciones</strong><p>Esta opción es visual; no modifica un algoritmo clínico.</p></div><span class="pill blue">${s.threshold}%</span></div><div class="field" style="margin:10px 0 0"><label for="threshold">Ajustar umbral de demostración</label><input id="threshold" type="range" min="40" max="90" step="5" value="${s.threshold}" data-setting="threshold" aria-label="Umbral simulado" /></div></section><section class="card card-pad">${header('Mis datos','Herramientas de exportación y reinicio')}<div class="settings-row"><div><strong>Exportar respaldo de registros</strong><p>Descargá un archivo JSON con todos los datos de esta sesión local.</p></div>${btn(`${icon('download')} JSON`,'export-json','outline')}</div><div class="settings-row"><div><strong>Restablecer datos de demostración</strong><p>Borra los registros de este prototipo y vuelve a los ejemplos iniciales.</p></div>${btn(`${icon('refresh')} Restablecer`,'reset-data','outline')}</div></section></div><div class="stack"><section class="card card-pad">${header('Estado de MigraRing','Próxima integración con hardware')}<div class="device-illustration"><div class="ring-model"></div></div><div class="device-state"><h3>Anillo no conectado</h3><p>Datos simulados · Bluetooth pendiente de desarrollo</p>${pill('Modo prototipo','purple')}</div><div class="section-rule"></div><div class="guidance-item"><span class="guidance-symbol">${icon('bluetooth')}</span><div><strong>Conectividad BLE</strong><p>No implementada. Requerirá firmware, protocolo seguro y pruebas con sensores.</p></div></div><div class="guidance-item"><span class="guidance-symbol green">${icon('lock')}</span><div><strong>Persistencia local</strong><p>Se guarda en localStorage de este navegador; no existe sincronización.</p></div></div></section><section class="card card-pad">${header('Uso responsable')}<p class="settings-privacy">Esta es una demostración de diseño y funcionalidad. No se debe utilizar para predecir migrañas reales, decidir tomar medicamentos o transmitir información médica confidencial. Una versión clínica requerirá validación, seguridad, consentimiento y cumplimiento regulatorio.</p></section></div></div>`}
function renderLearn(){
 return `${pageIntro('BIBLIOTECA DE MIGRAÑA','Aprender sobre migraña','Accedé a fuentes sanitarias confiables para comprender los síntomas, opciones de atención y líneas de investigación.')}
 <div class="inline-alert info" style="margin-bottom:20px">${icon('info')} Biblioteca de enlaces externos seleccionados. No existe una actualización automática de noticias ni un servicio de vigilancia científica en este prototipo.</div>
 <div class="learn-hero"><div><span class="eyebrow">INFORMACIÓN PARA EL PACIENTE</span><h2>Conocer tu migraña también es parte del cuidado</h2><p>La información médica cambia. Utilizá estos recursos como punto de partida y consultá con profesionales antes de cambiar cualquier tratamiento.</p></div><span class="learn-hero-illustration" aria-hidden="true">${icon('brain',72)}</span></div>
 <div class="learn-grid"><article class="card learn-card"><div class="learn-icon">${icon('brain',26)}</div><span class="eyebrow">GUÍA EN ESPAÑOL</span><h2>¿Qué es la migraña?</h2><p>Síntomas, fases, diagnóstico y posibles tratamientos explicados para pacientes.</p><a href="https://medlineplus.gov/spanish/migraine.html" target="_blank" rel="noopener noreferrer">Leer MedlinePlus ${icon('arrow',15)}</a></article>
 <article class="card learn-card"><div class="learn-icon">${icon('report',26)}</div><span class="eyebrow">SALUD PÚBLICA</span><h2>Migraña y otras cefaleas</h2><p>Información general de la Organización Mundial de la Salud y opciones de atención.</p><a href="https://www.who.int/es/news-room/fact-sheets/detail/headache-disorders" target="_blank" rel="noopener noreferrer">Consultar OMS ${icon('arrow',15)}</a></article>
 <article class="card learn-card"><div class="learn-icon">${icon('shield',26)}</div><span class="eyebrow">SEGUIMIENTO PERSONAL</span><h2>Preparar una consulta</h2><p>Documentá intensidad, duración, síntomas, tratamientos y posibles desencadenantes; compartí solo los datos que elijas.</p>${btn('Ver mis informes','nav','outline','data-section="reports"')}</article></div>
 <section class="card card-pad" style="margin-top:20px">${header('Qué se investiga en MigraRing','Objetivos de diseño, todavía no resultados clínicos')}<div class="research-chips"><span>Señales cardiovasculares</span><span>Sueño y hábitos</span><span>Actividad electrodérmica</span><span>Biomarcadores experimentales</span><span>Predicción individual</span></div><p class="settings-privacy">El proyecto propone investigar si determinadas señales fisiológicas tienen utilidad anticipatoria. El objetivo planteado en la matriz es sensibilidad ≥85 %, especificidad ≥80 % y al menos 30–60 minutos de anticipación; estas métricas no han sido verificadas en el prototipo.</p></section>`;
}
function renderRequirements(){
 const cards=[['Monitoreo y conexión','Muestreo cada 60 s · memoria local para al menos 48 h · reconexión BLE automática'],['Batería y carga','Autonomía objetivo ≥5 días · carga completa ≤45 min · protección térmica'],['Confort y materiales','Peso objetivo menor de 10 g · materiales biocompatibles · pruebas ISO 10993'],['Resistencia ambiental','Objetivo IP68 y ensayo 5 ATM como requisitos separados · corrosión y humedad']];
 return `<section class="card card-pad requirements-section">${header('Requisitos del anillo','Metas extraídas de la matriz, sin verificación experimental')}<div class="requirement-grid">${cards.map(([title,desc])=>`<div class="requirement-tile"><span class="requirement-pending">Pendiente de validar</span><strong>${title}</strong><p>${desc}</p></div>`).join('')}</div><p class="form-help">El prototipo no mide batería, señal BLE, sellado ni seguridad eléctrica. Estos indicadores aparecerán en vivo cuando existan firmware, hardware y pruebas.</p></section>`;
}
function renderSettingsV3(){return renderSettings()+`<section class="card card-pad settings-accessibility">${header('Accesibilidad durante una migraña','Modo prodrómico y alertas configurables')}<div class="settings-row"><div><strong>Modo calma / prodrómico</strong><p>Suaviza la paleta, reduce efectos visuales y agranda los controles para facilitar la lectura.</p></div><button type="button" aria-label="Activar modo calma" aria-pressed="${Boolean(state.settings.prodrome)}" class="switch ${state.settings.prodrome?'on':''}" data-action="toggle-setting" data-setting="prodrome"></button></div><div class="settings-row"><div><strong>Vibración suave en alertas de prueba</strong><p>Solo si el navegador y dispositivo admiten vibración. No equivale a la vibración del anillo.</p></div><button type="button" aria-label="Activar vibración" aria-pressed="${Boolean(state.settings.alertVibration)}" class="switch ${state.settings.alertVibration?'on':''}" data-action="toggle-setting" data-setting="alertVibration"></button></div><div class="settings-row"><div><strong>Tono de aviso en alertas de prueba</strong><p>Disponible solo cuando lo permita el navegador y tras una interacción del usuario. No se envían notificaciones del sistema.</p></div><button type="button" aria-label="Activar tono de aviso" aria-pressed="${Boolean(state.settings.alertTone)}" class="switch ${state.settings.alertTone?'on':''}" data-action="toggle-setting" data-setting="alertTone"></button></div><p class="form-help">Este modo es una adaptación visual inicial. No sustituye una auditoría WCAG 2.1 AA ni ensayos de usabilidad (SUS ≥85 es una meta de diseño).</p></section>
 <section class="card card-pad settings-privacy-enhanced">${header('Privacidad y consentimiento','Control de exportaciones de información')}<div class="privacy-banner">${icon('lock',23)}<div><strong>Datos locales, sin cifrado de grado clínico</strong><p>Tu información se almacena en localStorage de este navegador. No existe nube, autenticación, cifrado AES-256 ni conexión con un médico. Evitá registrar datos médicos sensibles reales en esta demostración.</p></div></div><div class="settings-row"><div><strong>Autorización para exportar</strong><p>Antes de descargar un CSV, PDF o respaldo JSON te pediremos confirmación. No se comparte automáticamente nada.</p></div><span class="pill green">Control activo</span></div><p class="form-help">Los requisitos de GDPR/HIPAA, TLS 1.3, OAuth 2.0 y HL7 FHIR corresponden a una implementación futura y su aplicabilidad deberá evaluarse jurídicamente.</p></section>${renderRequirements()}`;}
function exportConsentModal(kind){
 const titles={csv:'Exportar informe CSV',pdf:'Guardar informe PDF',json:'Exportar respaldo JSON'};const label=titles[kind]||'Exportar datos';
 return modalTemplate(label,'Confirmá cómo se usarán los registros de esta demostración.',`<form class="modal-body" id="export-consent-form"><input type="hidden" name="exportKind" value="${esc(kind)}"><div class="privacy-banner">${icon('shield',24)}<div><strong>Vos controlás la descarga</strong><p>El archivo se creará localmente. No enviaremos información al médico ni a servidores. Los registros iniciales son simulados y el almacenamiento actual no tiene seguridad clínica.</p></div></div><label class="consent-check"><input type="checkbox" name="consent" value="yes" required><span>Entiendo que el informe puede incluir datos ficticios y autorizo esta exportación local.</span></label><p class="form-help">Compartilo únicamente con quien elijas y revisá su contenido antes de enviarlo.</p></form>`,formButtons('export-consent-form','Confirmar descarga'));
}
function saveExportConsent(form){const f=formData(form);if(f.get('consent')!=='yes')return toast('Necesitamos tu confirmación para exportar.','error');const kind=f.get('exportKind');closeModal();if(kind==='csv')return exportCSV();if(kind==='json')return exportJSON();if(kind==='pdf')return window.print();}
function alertDemoFeedback(){
 if(state.settings.alertVibration && navigator.vibrate){try{navigator.vibrate([90,120,90]);}catch(e){}}
 if(state.settings.alertTone){try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(AudioContext){const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=260;gain.gain.value=.012;osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.18);osc.onended=()=>ctx.close();}}catch(e){}}
}
function render(){renderNavigation();let html=({overview:renderOverviewBio,monitoring:renderMonitoring,episodes:renderEpisodes,meds:renderMeds,reports:renderReportsBio,learn:renderLearn,settings:renderSettingsV3}[ui.section]||renderOverview)();document.querySelector('#app-content').innerHTML=html;renderNotifications();renderModal()}
function renderNotifications(){const popup=document.querySelector('#notification-popover');popup.classList.toggle('hidden',!ui.notifications);document.querySelector('.notification-trigger').setAttribute('aria-expanded',String(ui.notifications));const alerts=activeAlerts();popup.innerHTML=`<div class="popover-head"><strong>Notificaciones</strong>${pill(alerts.length?`${alerts.length} pendiente${alerts.length!==1?'s':''}`:'Sin pendientes',alerts.length?'pink':'green')}</div>${state.settings.notifications&&alerts.length?alerts.map(a=>`<div class="notification-item"><span class="notification-icon">${icon('bell')}</span><div><strong style="font-size:12px;color:#304066">Seguimiento de alerta simulada</strong><p>${a.ready||Date.now()>new Date(a.at).getTime()+a.horizon*3600000?'Ya podés indicar si tuviste migraña.':`Ventana estimada: ${horizonText(a.horizon)} desde la alerta.`}</p><button class="btn-text" data-action="view-alert" data-id="${esc(a.id)}">Revisar alerta →</button></div></div>`).join(''):`<div class="empty-state" style="padding:16px">${icon('check')}<strong>No hay avisos visibles</strong><p>${state.settings.notifications?'Tus alertas aparecerán aquí.':'Las notificaciones están desactivadas en Ajustes.'}</p></div>`}`}
function inputField(label,name,type='text',opts=''){
 return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" ${opts}></div>`;
}
function selectField(label,name,options,value=''){
 return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
}
function textareaField(label,name,placeholder=''){
 return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" placeholder="${esc(placeholder)}"></textarea></div>`;
}
function modalTemplate(title,subtitle,body,footer='',large=false){return `<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal-panel ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><div class="modal-header"><div><h2 id="modal-heading">${title}</h2><p>${subtitle}</p></div><button type="button" class="icon-button" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`}
function formButtons(formId,submit='Guardar registro'){return `${btn('Cancelar','close-modal','outline')}<button type="submit" form="${formId}" class="btn btn-primary">${icon('check')}${submit}</button>`}
function renderModal(){const root=document.querySelector('#modal-root');if(!ui.modal){root.innerHTML='';document.body.style.overflow='';return}document.body.style.overflow='hidden';const {type,id}=ui.modal;let content='';
 if(type==='plan'){content=modalTemplate('Planificar actividad','Organizá tu día. La app no predice ni modifica automáticamente tus compromisos.',`<form id="plan-form" class="modal-body">${inputField('Actividad','title','text','maxlength="100" placeholder="Ej. reunión, paseo o consulta" required')}${inputField('Fecha y hora','at','datetime-local',`value="${inputDateTime(new Date(Date.now()+86400000))}" required`)}${textareaField('Notas (opcional)','note','Plan alternativo, recordatorio personal...')}</form>`,formButtons('plan-form','Guardar actividad'));
 }else if(type==='export-consent'){content=exportConsentModal(id);
 }else if(type==='metric-reading'){
  content=renderBiomarkerModal(id);
 }else if(type==='reading'){
 content=modalTemplate('Cargar valores fisiológicos','Registro manual de una medición de seguimiento.',`<form id="reading-form" class="modal-body"><div class="form-grid">${inputField('Fecha y hora','at','datetime-local',`value="${inputDateTime(new Date())}" required`)}${inputField('Frecuencia cardíaca (lpm)','bpm','number','min="30" max="220" step="1" placeholder="Ej. 74" required')}${inputField('Variabilidad cardíaca (ms)','hrv','number','min="1" max="250" step="1" placeholder="Ej. 48" required')}${inputField('Temperatura cutánea (°C)','temp','number','min="20" max="43" step="0.1" placeholder="Ej. 33.5" required')}${inputField('Sueño (horas)','sleep','number','min="0" max="24" step="0.1" placeholder="Ej. 7.5" required')}${inputField('Actividad (pasos)','activity','number','min="0" max="100000" step="1" placeholder="Ej. 4500" required')}</div><div class="hint-box">${icon('info',14)} Esta carga no ejecuta ninguna predicción. Solo crea un registro histórico.</div></form>`,formButtons('reading-form'),true);
 } else if(type==='episode'){
 content=modalTemplate('Registrar episodio de migraña','Tu diario te ayuda a documentar lo que pasó.',`<form id="episode-form" class="modal-body"><div class="form-grid">${inputField('Fecha y hora de inicio','at','datetime-local',`value="${inputDateTime(new Date())}" required`)}${inputField('Intensidad (1 a 10)','intensity','number','min="1" max="10" value="5" required')}${inputField('Duración (horas)','duration','number','min="0.5" max="168" step="0.5" value="2" required')}${selectField('¿Hubo alerta previa?','alertPrior',['No','Sí','No recuerdo'])}</div><div class="field"><span>Síntomas presentes</span><div style="display:flex;flex-wrap:wrap;gap:0 17px">${['Fotofobia','Náuseas','Aura','Sensibilidad al sonido','Mareos','Otro'].map(s=>`<label class="check-row" style="margin:4px 0 9px"><input type="checkbox" name="symptom" value="${esc(s)}">${esc(s)}</label>`).join('')}</div></div>${inputField('Posibles desencadenantes','triggers','text','placeholder="Ej. estrés, falta de sueño, luces"')}${inputField('Medicación utilizada','medication','text','placeholder="Nombre y dosis si corresponde"')}${textareaField('Notas adicionales','notes','¿Cómo empezó? ¿Qué hiciste?') }<div class="hint-box">Si no recibiste alerta, este episodio se guarda igualmente para revisar los casos no anticipados.</div></form>`,formButtons('episode-form'),true);
 }else if(type==='med'){
 content=modalTemplate('Agregar medicamento','Anotá únicamente tratamientos ya indicados por tu profesional.',`<form id="med-form" class="modal-body">${inputField('Nombre del medicamento','name','text','maxlength="100" placeholder="Nombre indicado por el profesional" required')}<div class="form-grid">${inputField('Dosis indicada','dose','text','maxlength="100" placeholder="Según mi prescripción" required')}${selectField('Tipo de uso','purpose',['Según indicación médica','Preventivo','Durante episodio','Otro'])}${inputField('Fecha de inicio','start','date',`value="${dayKey(new Date())}" required`)}</div>${textareaField('Observaciones','notes','Instrucciones personales ya pautadas por el médico')}</form>`,formButtons('med-form'));
 }else if(type==='dose'){
 const med=state.medications.find(m=>m.id===id);if(!med){ui.modal=null;return renderModal()}
 content=modalTemplate('Registrar una toma',`${esc(med.name)} · Registro personal`, `<form id="dose-form" class="modal-body"><input type="hidden" name="medId" value="${esc(med.id)}">${inputField('Fecha y hora de la toma','at','datetime-local',`value="${inputDateTime(new Date())}" required`)}${inputField('Cantidad / dosis tomada','amount','text','maxlength="100" placeholder="Según tu prescripción" required')}${textareaField('Comentarios','note','Ej. hora de inicio de síntomas')}<div class="hint-box">Este registro no cambia ni recomienda tu tratamiento.</div></form>`,formButtons('dose-form','Guardar toma'));
 }else if(type==='alert'){
 const alert=state.alerts.find(a=>a.id===id)||latestAlert();if(!alert){ui.modal=null;return renderModal()}
 const endAt=new Date(new Date(alert.at).getTime()+alert.horizon*3600000),ready=alert.ready||Date.now()>=endAt.getTime();
 content=modalTemplate('Detalle de alerta simulada','Seguimiento de la predicción ficticia del prototipo.',`<div class="modal-body"><div class="alert-hero"><div class="big-risk">${alert.risk}%</div><div><h3>Ejemplo de alerta para ${horizonText(alert.horizon)}</h3><p>Alerta creada el ${formatDate(alert.at)} a las ${formatHour(alert.at)}. El objetivo de diseño es anticipar entre 30 y 60 minutos; este porcentaje es ficticio y no cumple aún los criterios clínicos de sensibilidad o especificidad.</p></div></div><div style="margin-top:20px"><h3 class="section-heading">Acciones de autocuidado</h3><div class="action-list"><div class="action-tile"><span class="left">${icon('water')}</span><div><h3>Hidratación y descanso</h3><p>Registrar hábitos y reducir estímulos si te resulta útil.</p></div></div><div class="action-tile"><span class="left">${icon('clipboard')}</span><div><h3>Seguí tu plan médico</h3><p>Solo tomá medicamentos conforme a indicaciones ya recibidas.</p></div></div><div class="action-tile"><span class="left">${icon('clock')}</span><div><h3>Respondé al finalizar la ventana</h3><p>Indicá si ocurrió o no la migraña y si seguiste las recomendaciones.</p></div></div></div></div><div class="inline-alert info" style="margin-top:20px">${icon('info')} ${ready?'La ventana de prueba está terminada. Ya podés registrar el resultado.':`La ventana terminaría el ${formatDate(endAt)} a las ${formatHour(endAt)}. Podés simular su finalización para probar el circuito.`}</div></div>`,`${btn('Cerrar','close-modal','outline')}${ready?btn('Registrar resultado','alert-feedback','primary',`data-id="${esc(alert.id)}"`):btn('Simular fin de ventana','finish-window','primary',`data-id="${esc(alert.id)}"`)}`,true);
 }else if(type==='feedback'){
 const alert=state.alerts.find(a=>a.id===id);if(!alert){ui.modal=null;return renderModal()}
 content=modalTemplate('¿Qué pasó luego de la alerta?','Respondé al finalizar el período estimado para registrar el resultado.',`<form id="feedback-form" class="modal-body"><input type="hidden" name="alertId" value="${esc(alert.id)}"><div class="field"><span>¿Tuviste migraña durante el período indicado? *</span><div class="risk-outcome"><label class="choice-card"><input type="radio" name="migraine" value="yes" required> Sí, tuve migraña</label><label class="choice-card"><input type="radio" name="migraine" value="no" required> No tuve migraña</label></div></div><div id="feedback-episode-fields" class="hidden"><div class="form-grid">${inputField('Intensidad (1–10)','intensity','number','min="1" max="10" value="5"')}${inputField('Duración (horas)','duration','number','min="0.5" max="168" step="0.5" value="2"')}</div>${inputField('Síntomas','symptoms','text','placeholder="Ej. fotofobia, náuseas"')}</div>${selectField('¿Seguiste las recomendaciones generales?','followed',['Sí','Parcialmente','No','No aplica'])}${inputField('¿Qué hiciste?','actions','text','maxlength="250" placeholder="Ej. descansé, tomé agua..."')}${inputField('Medicación utilizada (si corresponde)','medication','text','maxlength="120" placeholder="Solo si ya tenías indicación médica"')}${textareaField('Notas para tu seguimiento','notes','Información que te gustaría recordar')}<div class="hint-box">Guardaremos tanto los resultados positivos como negativos. El aprendizaje del modelo es una función futura, no implementada.</div></form>`,formButtons('feedback-form','Guardar resultado'),true);
 }else if(type==='device'){
 content=modalTemplate('Integración con el anillo','Estado técnico actual de MigraRing.',`<div class="modal-body"><div class="device-illustration"><div class="ring-model"></div></div><div class="inline-alert info">${icon('bluetooth')} La sincronización Bluetooth no está implementada en esta iteración.</div><p class="settings-privacy" style="margin-top:17px">Para conectarlo al hardware real habrá que acordar los sensores y datos transmitidos, la especificación GATT de Bluetooth Low Energy, el emparejamiento seguro y el almacenamiento de información sanitaria. Las lecturas actuales son ficticias o manuales.</p></div>`,btn('Entendido','close-modal','primary'));
 }else if(type==='reset'){
 content=modalTemplate('Restablecer demostración','Esta acción reemplaza tus registros locales por los ejemplos originales.',`<div class="modal-body"><div class="inline-alert">${icon('info')} Perderás las mediciones, episodios y medicamentos que hayas añadido en este navegador. Si querés conservarlos, exportá antes un respaldo JSON desde Configuración.</div></div>`,btn('Cancelar','close-modal','outline')+btn('Sí, restablecer','confirm-reset','pink'));
 }else if(type==='delete'){
 const med=state.medications.find(m=>m.id===id);content=modalTemplate('Eliminar medicamento','Esta acción también quita sus registros de tomas.',`<div class="modal-body"><p class="settings-privacy">¿Querés eliminar <strong>${esc(med?.name||'este medicamento')}</strong> del prototipo?</p></div>`,btn('Cancelar','close-modal','outline')+btn('Eliminar','confirm-delete','pink',`data-id="${esc(id)}"`));
 }
 root.innerHTML=content;const focus=root.querySelector('input:not([type=hidden]),button[data-action=close-modal]');focus?.focus({preventScroll:true});
}
let toastTimeout=null;function toast(message,type='success'){
 const root=document.querySelector('#toast-root');root.innerHTML=`<div class="toast" role="status">${icon(type==='error'?'info':'check')}${esc(message)}</div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>root.innerHTML='',4000);
}
function go(section){ui.section=section;ui.mobileMenu=false;ui.notifications=false;ui.modal=null;render();window.scrollTo({top:0,behavior:'smooth'})}
function openModal(type,id=null){ui.modal={type,id};ui.notifications=false;renderNotifications();renderModal()}
function closeModal(){ui.modal=null;renderModal()}
function csvValue(s){let v=String(s??'');if(/^[\s]*[=+@\-]/.test(v))v="'"+v;return `"${v.replace(/"/g,'""')}"`}
function download(name,contents,mime){const file=new Blob([contents],{type:mime});const href=URL.createObjectURL(file);const a=document.createElement('a');a.href=href;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),3000)}
function exportCSV(){const {ep,r,reviewed}=reportSummary();let lines=['MIGRARING - REPORTE PERSONAL DE DEMOSTRACIÓN',`Período: ${reportWindow().label}`,`Filtro de síntomas: ${ui.reportSymptom==='all'?'Todos':ui.reportSymptom}`,'Aviso: datos iniciales simulados; no constituyen diagnóstico clínico','','EPISODIOS', ['Fecha','Intensidad / 10','Duración (horas)','Síntomas','Posibles desencadenantes','Medicación','Fuente'].map(csvValue).join(',')];
 sortByDate(ep).forEach(e=>lines.push([inputDateTime(e.at),e.intensity,e.duration,(e.symptoms||[]).join('; '),e.triggers,e.medication,e.source].map(csvValue).join(',')));
 lines.push('','LECTURAS', ['Fecha','Pulso lpm','VFC ms','Temp cutánea °C','Sueño horas','Actividad pasos','Origen'].map(csvValue).join(','));sortByDate(r).forEach(x=>lines.push([inputDateTime(x.at),x.bpm,x.hrv,x.temp,x.sleep,x.activity,x.source].map(csvValue).join(',')));
 lines.push('','RESULTADOS DE ALERTAS',['Fecha','Riesgo simulado %','Migraña','Recomendaciones','Acciones','Medicación'].map(csvValue).join(','));reviewed.forEach(a=>lines.push([inputDateTime(a.at),a.risk,a.feedback?.migraine==='yes'?'Sí':'No',a.feedback?.followed||'',a.feedback?.actions||'',a.feedback?.medication||''].map(csvValue).join(',')));
 lines.push('','BIOMARCADORES', ['Fecha','Categoría','Parámetro','Valor','Unidad','Origen','Notas'].map(csvValue).join(','));
 const csvMetrics=BIO_METRICS.flatMap(m=>metricSamples(m.id).filter(inReportWindow).map(x=>({m,x})));
 csvMetrics.sort((a,b)=>new Date(b.x.at)-new Date(a.x.at)).forEach(({m,x})=>lines.push([inputDateTime(x.at),BIO_GROUPS.find(g=>g.id===m.group)?.name||'',m.name,x.value,m.unit,bioSource(x.source),x.note||''].map(csvValue).join(',')));
 download(`MigraRing_informe_${dayKey(new Date())}.csv`,'\ufeff'+lines.join('\r\n'),'text/csv;charset=utf-8');toast('Informe CSV generado. Revisá la carpeta de descargas.')}
function exportJSON(){download(`MigraRing_respaldo_${dayKey(new Date())}.json`,JSON.stringify({exportedAt:new Date().toISOString(),notice:'Prototipo, datos no validados',data:state},null,2),'application/json');toast('Respaldo JSON descargado.')}
function validDate(v){const d=new Date(v);return Number.isNaN(d.getTime())?null:d.toISOString()}
function formData(form){return new FormData(form)}
function saveReading(form){const f=formData(form);const at=validDate(f.get('at'));if(!at)return toast('Comprobá la fecha de la medición.','error');let r={id:uid(),at,source:'manual',risk:null};for(const field of ['bpm','hrv','temp','sleep','activity'])r[field]=Number(f.get(field));state.readings.push(r);persist();closeModal();render();toast('Medición guardada en tu historial.')}
function saveEpisode(form){const f=formData(form);const at=validDate(f.get('at'));if(!at)return toast('Comprobá la fecha del episodio.','error');state.episodes.push({id:uid(),at,intensity:Number(f.get('intensity')),duration:Number(f.get('duration')),symptoms:f.getAll('symptom').map(String),triggers:String(f.get('triggers')||'').trim(),medication:String(f.get('medication')||'').trim(),notes:String(f.get('notes')||'').trim(),source:f.get('alertPrior')==='Sí'?'alert':'manual',followed:null});persist();closeModal();render();toast('Episodio registrado. Gracias por completar tu diario.')}
function saveMed(form){const f=formData(form);state.medications.push({id:uid(),name:String(f.get('name')).trim(),dose:String(f.get('dose')).trim(),purpose:String(f.get('purpose')),start:String(f.get('start')),notes:String(f.get('notes')||'').trim(),logs:[]});persist();closeModal();render();toast('Medicamento agregado al listado.')}
function saveDose(form){const f=formData(form);const med=state.medications.find(m=>m.id===f.get('medId'));if(!med)return toast('No se encontró el medicamento.','error');const at=validDate(f.get('at'));if(!at)return toast('Comprobá la fecha y la hora.','error');med.logs.push({id:uid(),at,amount:String(f.get('amount')||'').trim(),note:String(f.get('note')||'').trim()});persist();closeModal();render();toast('Toma agregada al historial.')}
function saveFeedback(form){const f=formData(form);const alert=state.alerts.find(a=>a.id===f.get('alertId'));if(!alert||alert.status!=='pending')return toast('La alerta ya no está pendiente.','error');const migraine=f.get('migraine');if(!['yes','no'].includes(migraine))return toast('Elegí si ocurrió la migraña.','error');const actions=String(f.get('actions')||'').trim(),medication=String(f.get('medication')||'').trim();alert.status='resolved';alert.feedback={at:new Date().toISOString(),migraine,followed:String(f.get('followed')||''),actions,medication,notes:String(f.get('notes')||'').trim()};if(migraine==='yes'){state.episodes.push({id:uid(),at:new Date().toISOString(),intensity:Number(f.get('intensity'))||5,duration:Number(f.get('duration'))||2,symptoms:String(f.get('symptoms')||'').split(',').map(s=>s.trim()).filter(Boolean),triggers:'No identificado',medication,notes:String(f.get('notes')||'').trim(),source:'alert',followed:alert.feedback.followed})}persist();closeModal();render();toast('Resultado guardado. El histórico refleja la respuesta; no hay aprendizaje automático activo.')}
const FORM_HANDLERS={'bio-reading-form':saveBioReading,'reading-form':saveReading,'episode-form':saveEpisode,'med-form':saveMed,'dose-form':saveDose,'feedback-form':saveFeedback,'export-consent-form':saveExportConsent,'plan-form':savePlan};
document.addEventListener('submit',ev=>{const form=ev.target;if(FORM_HANDLERS[form.id]){ev.preventDefault();FORM_HANDLERS[form.id](form)}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.matches('input[name="migraine"]'))document.querySelector('#feedback-episode-fields')?.classList.toggle('hidden',t.value!=='yes');if(t.matches('[data-report-filter]')){const kind=t.dataset.reportFilter;if(kind==='period')ui.reportRange=t.value==='custom'?'custom':Number(t.value);if(kind==='symptom')ui.reportSymptom=t.value;if(kind==='metric')ui.reportMetric=t.value;return render()}if(t.matches('[data-report-date]')){if(t.dataset.reportDate==='from')ui.reportFrom=t.value;else ui.reportTo=t.value;return render()}if(t.matches('input[data-setting="threshold"]')){state.settings.threshold=Number(t.value);persist();render()}});
document.addEventListener('input',ev=>{
 if(ev.target.id==='bio-search'){ui.metricSearch=ev.target.value;const root=document.querySelector('#biomarker-card-grid');if(root)root.innerHTML=renderBiomarkerCards();}
});
document.addEventListener('click',ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;const id=el.dataset.id;
 if(action==='modal-backdrop'){if(ev.target===el)closeModal();return}
 if(action==='nav')return go(el.dataset.section);
 if(action==='toggle-menu'){ui.mobileMenu=!ui.mobileMenu;return renderNavigation()}
 if(action==='toggle-notifications'){ui.notifications=!ui.notifications;return renderNotifications()}
 if(action==='new-episode')return openModal('episode');if(action==='new-plan')return openModal('plan');if(action==='toggle-plan'){const plan=state.plans.find(x=>x.id===id);if(plan){plan.status=plan.status==='done'?'planned':'done';persist();render()}return}if(action==='delete-plan'){state.plans=state.plans.filter(x=>x.id!==id);persist();render();return}
 if(action==='open-catalog'){ui.monitorMode='catalog';return go('monitoring')}
 if(action==='bio-overview'){ui.monitorMode='overview';return go('monitoring')}
 if(action==='bio-filter'){ui.metricCategory=el.dataset.value;return render()}
 if(action==='select-metric'){if(BIO_BY_ID[id])ui.metricSelected=id;return render()}
 if(action==='new-bio-reading'){const metricId=id||ui.metricSelected;if(BIO_BY_ID[metricId]&&BIO_BY_ID[metricId].kind!=='ai')return openModal('metric-reading',metricId);return toast('Este indicador requiere un modelo validado.','error')}
 if(action==='new-reading')return openModal('reading');
 if(action==='new-med')return openModal('med');
 if(action==='dose')return openModal('dose',id);
 if(action==='device-info')return openModal('device');
 if(action==='view-alert'){const target=id||latestAlert()?.id;if(target)return openModal('alert',target);return toast('No hay alertas pendientes.','error')}
 if(action==='close-modal')return closeModal();
 if(action==='alert-feedback')return openModal('feedback',id);
 if(action==='finish-window'){const a=state.alerts.find(a=>a.id===id);if(a){a.ready=true;persist();openModal('feedback',id)}return}
 if(action==='period'){ui.period=Number(el.dataset.period);return render()}
 if(action==='episode-filter'){ui.episodeFilter=el.dataset.value;return render()}
 if(action==='report-range'){ui.reportRange=el.dataset.period==='custom'?'custom':Number(el.dataset.period);return render()}
 if(action==='simulate-alert'){const at=new Date().toISOString();const a={id:uid(),at,horizon:1,risk:78,status:'pending',ready:false,feedback:null};state.alerts.push(a);persist();render();openModal('alert',a.id);alertDemoFeedback();return toast('Alerta de prueba creada; no es una predicción real.')}
 if(action==='toggle-setting'){const name=el.dataset.setting;state.settings[name]=!state.settings[name];persist();return render()}
 if(action==='export-csv')return openModal('export-consent','csv');
 if(action==='export-json')return openModal('export-consent','json');
 if(action==='print-report'){if(ui.section!=='reports')go('reports');return openModal('export-consent','pdf')}
 if(action==='reset-data')return openModal('reset');
 if(action==='confirm-reset'){state=seed();persist();closeModal();go('overview');return toast('Se recuperaron los datos de demostración.')}
 if(action==='delete-med')return openModal('delete',id);
 if(action==='confirm-delete'){state.medications=state.medications.filter(m=>m.id!==id);persist();closeModal();render();return toast('Medicamento eliminado del historial.')}
});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if(ui.modal)closeModal();else if(ui.notifications){ui.notifications=false;renderNotifications()}else if(ui.mobileMenu){ui.mobileMenu=false;renderNavigation()}}});
render();
